describe('test deploy support ros', () => {
  const requestOption = {
    method: 'POST'
  };

  let rosClient;
  let requestStub;
  let restoreProcess;
  let deployByRos;
  beforeEach(() => {
    restoreProcess = setProcess({
      ACCOUNT_ID: 'testAccountId',
      ACCESS_KEY_ID: 'testKeyId',
      ACCESS_KEY_SECRET: '[REDACTED]',
      FC_ENDPOINT: 'test fc endpoint',
      REGION: 'cn-beijing'
    });

